```sql
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create function public.is_suspended(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select suspended from public.accounts where user_id = p_user_id), false);
$$;

create function public.has_active_share(p_file_id bigint, p_user_id uuid, p_require_edit boolean default false)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.file_shares
    where file_id = p_file_id and shared_with = p_user_id and can_edit = p_require_edit and expires_at > now()
  );
$$;

create policy "files_select"
on public.files
for select
to authenticated
using (owner_id = auth.uid() or public.has_active_share(id, auth.uid(), false));

create policy "files_insert"
on public.files
for insert
to authenticated
with check (owner_id = auth.uid() and not public.is_suspended(auth.uid()));

create policy "files_update"
on public.files
for update
to authenticated
using (owner_id = auth.uid() or public.has_active_share(id, auth.uid(), true))
with check (owner_id = auth.uid() or public.has_active_share(id, auth.uid(), true));

create policy "files_delete"
on public.files
for delete
to authenticated
using (owner_id = auth.uid());

create policy "file_shares_select"
on public.file_shares
for select
to authenticated
using (public.is_suspended(auth.uid()) = false and (shared_with = auth.uid() or exists (select 1 from public.files where id = file_id and owner_id = auth.uid())));

create policy "file_shares_insert"
on public.file_shares
for insert
to authenticated
with check (exists (select 1 from public.files where id = file_id and owner_id = auth.uid()) and public.is_suspended(auth.uid()) = false);

create policy "file_shares_update"
on public.file_shares
for update
to authenticated
using (exists (select 1 from public.files where id = file_id and owner_id = auth.uid()))
with check (exists (select 1 from public.files where id = file_id and owner_id = auth.uid()));

create policy "file_shares_delete"
on public.file_shares
for delete
to authenticated
using (exists (select 1 from public.files where id = file_id and owner_id = auth.uid()));

create policy "accounts_select"
on public.accounts
for select
to authenticated
using (user_id = auth.uid());

revoke all on public.accounts from anon, authenticated;
revoke all on public.files from anon, authenticated;
revoke all on public.file_shares from anon, authenticated;

grant select on public.accounts to authenticated;
grant select, insert, update, delete on public.files to authenticated;
grant select, insert, update, delete on public.file_shares to authenticated;

grant usage, select on all sequences in schema public to authenticated;

grant all on public.accounts, public.files, public.file_shares to service_role;
