create function public.invoice_status_transition_ok(p_id bigint, p_old_status text, p_new_status text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.invoices i where i.id = p_id and i.status = p_old_status
  ) and (
    (p_old_status = 'draft' and p_new_status in ('draft', 'sent'))
    or (p_old_status = 'sent' and p_new_status in ('paid', 'void') and public.is_finance_staff())
  )
$$;

