create function public.invoice_before_update()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if new.created_by is distinct from old.created_by then
    raise exception 'created_by cannot be changed';
  end if;
  if new.customer is distinct from old.customer or new.amount is distinct from old.amount then
    if old.status <> 'draft' then
      raise exception 'customer and amount can only be changed on draft invoices';
    end if;
  end if;
  if new.status is distinct from old.status then
    if not public.invoice_status_transition_ok(old.id, old.status, new.status) then
      raise exception 'invalid status transition';
    end if;
  end if;
  return new;
end
$$;

