create policy orgs_select on public.orgs
  for select to authenticated
  using (exists (select 1 from public.org_members m where m.org_id = orgs.id and m.user_id = auth.uid()));

create policy org_members_select on public.org_members
  for select to authenticated
  using (exists (select 1 from public.org_members m where m.org_id = org_members.org_id and m.user_id = auth.uid()));

create policy invites_select on public.invites
  for select to authenticated
  using (exists (select 1 from public.org_members m where m.org_id = invites.org_id and m.role = 'admin' and m.user_id = auth.uid()));

create policy invites_insert on public.invites
  for insert to authenticated
  with check (invited_by = auth.uid() and accepted_at is null and expires_at > now());

create policy invites_delete on public.invites
  for delete to authenticated
  using (exists (select 1 from public.org_members m where m.org_id = invites.org_id and m.role = 'admin' and m.user_id = auth.uid()));

create function public.accept_invite(p_token text) returns bigint
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_org bigint;
  v_role text;
begin
  if v_uid is null then
    raise exception 'not signed in';
  end if;
  select i.org_id, i.role into v_org, v_role from public.invites i where i.token = p_token for update;
  if not found then
    raise exception 'unknown token';
  end if;
  if i.accepted_at is not null or i.expires_at <= now() then
    raise exception 'invite expired or already accepted';
  end if;
  if lower(i.email) <> lower(auth.jwt() ->> 'email') then
    raise exception 'email does not match';
  end if;
  insert into public.org_members (org_id, user_id, role) values (v_org, v_uid, v_role);
  update public.invites set accepted_at = now() where token = p_token;
  return v_org;
end
$$;
