create function public.is_org_member(p_org_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.org_members m where m.org_id = p_org_id and m.user_id = auth.uid())
$$;

create function public.is_org_admin(p_org_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.org_members m where m.org_id = p_org_id and m.user_id = auth.uid() and m.role = 'admin')
$$;

create function public.accept_invite(p_token text) returns bigint
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_org_id bigint;
  v_role text;
begin
  if v_uid is null then
    raise exception 'not signed in';
  end if;
  select i.org_id, i.role into v_org_id, v_role from public.invites i where i.token = p_token for update;
  if not found then
    raise exception 'unknown invite';
  end if;
  if i.accepted_at is not null then
    raise exception 'invite already accepted';
  end if;
  if i.expires_at <= now() then
    raise exception 'invite expired';
  end if;
  if lower(coalesce((select auth.jwt() ->> 'email'), '')) <> lower(v.email) then
    raise exception 'email does not match';
  end if;
  insert into public.org_members (org_id, user_id, role) values (v_org_id, v_uid, v_role);
  update public.invites set accepted_at = now() where token = p_token;
  return v_org_id;
end
$$;

