returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.issues i where i.id = p_issue_id and (not i.is_confidential or public.is_project_member(i.project_id, auth.uid()) and exists (select 1 from public.project_members m where m.project_id = i.project_id and m.role = 'maintainer' and m.user_id = auth.uid()))
  );
$$;

create function public.can_update_issue(p_issue_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.issues i where i.id = p_issue_id and public.is_project_member(i.project_id, auth.uid()) and exists (select 1 from public.project_members m where m.project_id = i.project_id and m.role in ('developer', 'maintainer') and m.user_id = auth.uid())
  );
$$;

create function public.can_make_confidential(p_issue_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.issues i where i.id = p_issue_id and public.is_project_member(i.project_id, auth.uid()) and exists (select 1 from public.project_members m where m.project_id = i.project_id and m.role = 'maintainer' and m.user_id = auth.uid())
  );
