returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.issues i where i.id = p_issue_id and i.is_confidential and (i.reporter_id = auth.uid() or i.assignee_id = auth.uid() or public.is_project_member(i.project_id, auth.uid()) and exists (select 1 from public.project_members m where m.project_id = i.project_id and m.role = 'maintainer' and m.user_id = auth.uid()))
  );
$$;

