on public.project_members
for select
to authenticated
using (public.is_project_member(project_id, auth.uid()));

create policy issues_select_members
on public.issues
for select
to authenticated
using (not is_confidential or public.is_project_member_of_confidential_issue(id));

create policy issues_insert_members
on public.issues
for insert
to authenticated
with check (reporter_id = auth.uid() and status = 'open' and public.is_project_member(project_id, auth.uid()));

