on public.issues
for update
to authenticated
using (can_update_issue(id))
with check (
  can_update_issue(id) and
  (not is_confidential or can_make_confidential(id)) and
  (not exists (select 1 from public.project_members m where m.project_id = project_id and m.role = 'reporter' and m.user_id = auth.uid()))
);

