on public.pharmacists
for select
to authenticated
using (true);

create policy "prescriptions_select_authenticated"
on public.prescriptions
for select
to authenticated
using (
  patient_id = auth.uid()
  or exists (select 1 from public.pharmacists where user_id = auth.uid())
);

create policy "dispenses_select_authenticated"
on public.dispenses
for select
to authenticated
using (
  exists (select 1 from public.prescriptions p where p.id = prescription_id and p.patient_id = auth.uid())
  or exists (select 1 from public.pharmacists where user_id = auth.uid())
);

create function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_pharmacist uuid := auth.uid();
  v_refills integer;
  v_patient uuid;
begin
  if v_pharmacist is null then
    raise exception 'not authenticated';
  end if;

  if not exists (select 1 from public.pharmacists where user_id = v_pharmacist) then
    raise exception 'caller is not a pharmacist';
  end if;

  select refills_left, patient_id into v_refills, v_patient
  from public.prescriptions
  where id = p_prescription_id
  for update;

  if not found then
    raise exception 'prescription not found';
  end if;

  if v_patient = v_pharmacist then
    raise exception 'cannot dispense own prescription';
  end if;

  if v_refills <= 0 then
    raise exception 'no refills left';
  end if;

  if v_patient is not null and v_patient > auth.uid() then
    raise exception 'prescription expired';
  end if;

  v_refills := v_refills - 1;

  update public.prescriptions
  set refills_left = v_refills
  where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist, now());

  return v_refills;
end;
$$;

