```sql
alter table public.envelopes enable row level security;
alter table public.envelope_recipients enable row level security;

revoke all on public.envelopes from anon, authenticated;
revoke all on public.envelope_recipients from anon, authenticated;

grant select on public.envelopes to authenticated;
grant select on public.envelope_recipients to authenticated;

create policy "envelopes_select_senders_recipients"
on public.envelopes
for select
to authenticated
using (sender_id = auth.uid() or exists (select 1 from public.envelope_recipients r where r.envelope_id = envelopes.id and r.user_id = auth.uid()));

create policy "envelope_recipients_select_senders_recipients"
on public.envelope_recipients
for select
to authenticated
using (exists (select 1 from public.envelopes e where e.id = envelope_recipients.envelope_id and (e.sender_id = auth.uid() or envelope_recipients.user_id = auth.uid())));

create function public.sign_envelope(p_envelope_id bigint) returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_status text;
  v_signed_at timestamptz;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id for update;
  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if not exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid) then
    raise exception 'not a recipient';
  end if;

  if exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid and r.signed_at is not null) then
    raise exception 'already signed';
  end if;

  select sign_order into v_signed_at from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.user_id = v_uid;
  if v_signed_at is null then
    raise exception 'recipient not found';
  end if;

  if exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.sign_order < v_signed_at and r.signed_at is null) then
    raise exception 'previous recipient has not signed';
  end if;

  update public.envelope_recipients r set signed_at = now() where r.envelope_id = p_envelope_id and r.user_id = v_uid;

  if exists (select 1 from public.envelope_recipients r where r.envelope_id = p_envelope_id and r.signed_at is null) then
    v_status := 'sent';
  else
    update public.envelopes e set status = 'completed' where e.id = p_envelope_id;
    v_status := 'completed';
  end if;

  return v_status;
end;
$$;

create function public.void_envelope(p_envelope_id bigint) returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope from public.envelopes where id = p_envelope_id for update;
  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.sender_id <> v_uid then
    raise exception 'only sender can void';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  update public.envelopes e set status = 'voided' where e.id = p_envelope_id;
