```sql
alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

create function public.is_reviewer()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.reviewers r where r.user_id = auth.uid())
$$;

create function public.proposal_decided(p_proposal_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.proposals p where p.id = p_proposal_id and p.status != 'submitted')
$$;

create function public.reviews_before_update()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if new.proposal_id is distinct from old.proposal_id
     or new.reviewer_id is distinct from old.reviewer_id then
    raise exception 'reviews: cannot move to another proposal or another reviewer';
  end if;
  if not exists (select 1 from public.reviews r where r.proposal_id = old.proposal_id and r.reviewer_id = old.reviewer_id) then
    raise exception 'reviews: no such review';
  end if;
  if not public.is_reviewer() then
    raise exception 'reviews: not a reviewer';
  end if;
  if public.proposal_decided(old.proposal_id) is false then
    raise exception 'reviews: proposal is still undecided';
  end if;
  return new;
end
$$;

create trigger reviews_before_update
before update on public.reviews
for each row execute function public.reviews_before_update();

create policy "R1 R2 R3 R4: proposals select"
on public.proposals
for select
to authenticated
using (speaker_id = auth.uid() or public.is_reviewer());

create policy "R2: proposals insert as self, always submitted"
on public.proposals
for insert
to authenticated
with check (speaker_id = auth.uid() and status = 'submitted');

create policy "R2: proposals update own undecided"
on public.proposals
for update
to authenticated
using (speaker_id = auth.uid() and status = 'submitted')
with check (speaker_id = auth.uid() and status in ('submitted', 'accepted', 'rejected'));

create policy "R3 R4: reviews select own or decided proposal"
on public.reviews
for select
to authenticated
using (reviewer_id = auth.uid() or public.proposal_decided(proposal_id));

create policy "R3: reviews insert own, undecided, not own proposal"
on public.reviews
for insert
to authenticated
with check (
  reviewer_id = auth.uid()
  and public.is_reviewer()
  and not exists (select 1 from public.reviewers r where r.user_id = auth.uid())
  and public.proposal_decided(proposal_id) is false
);

create policy "R3: reviews update own, undecided"
on public.reviews
for update
to authenticated
using (reviewer_id = auth.uid() and public.proposal_decided(proposal_id))
with check (reviewer_id = auth.uid() and public.proposal_decided(proposal_id));

revoke all on public.reviewers from anon, authenticated;
grant select on public.reviewers to authenticated;

revoke all on public.proposals from anon, authenticated;
grant select, insert, update on public.proposals to authenticated;

revoke all on public.reviews from anon, authenticated;
grant select, insert, update on public.reviews to authenticated;

grant all on public.reviewers, public.proposals, public.reviews to service_role;
```

```sql
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

create function public.is_hoa_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.hoa_admins where user_id = auth.uid())
$$;

create function public.active_permits_for_unit(p_unit_id bigint)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::integer
  from public.permits
  where unit_id = p_unit_id and revoked = false and valid_until >= current_date
$$;

create function public.enforce_permit_insert()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if new.revoked then
    raise exception 'new permits cannot be revoked';
  end if;

  if new.valid_until < current_date or new.valid_until > current_date + interval '365 days' then
    raise exception 'permit must be valid for at most 365 days from today';
  end if;

  if public.active_permits_for_unit(new.unit_id) >= 2 then
    raise exception 'unit already has 2 active permits';
  end if;

  return new;
end
$$;

create function public.enforce_permit_update()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if new.id <> old.id or new.unit_id <> old.unit_id then
    raise exception 'cannot change permit id or unit';
  end if;

  if old.revoked and new.revoked = false then
    raise exception 'permits cannot be un-revoked';
  end if;

  if old.revoked = false and new.revoked = true then
    if not public.is_hoa_admin() then
      raise exception 'only HOA admins can revoke permits';
    end if;
  elsif old.revoked = true and new.revoked = true then
    raise exception 'cannot modify revoked permits';
  else
    if not public.is_hoa_admin() then
      raise exception 'only HOA admins can revoke permits';
    end if;
  end if;

  if new.valid_until <> old.valid_until then
    raise exception 'only plate can be changed';
  end if;

  return new;
end
$$;

create trigger enforce_permit_insert
before insert on public.permits
for each row execute function public.enforce_permit_insert();

create trigger enforce_permit_update
before update on public.permits
for each row execute function public.enforce_permit_update();

create policy "residents_select_own_or_unit"
on public.residents
for select
to authenticated
using (user_id = auth.uid() or exists (select 1 from public.permits where unit_id = residents.unit_id));

create policy "permits_select_own_or_unit_or_hoa"
on public.permits
for select
to authenticated
using (exists (select 1 from public.residents where unit_id = permits.unit_id and user_id = auth.uid()) or public.is_hoa_admin());

create policy "permits_insert_own_unit_with_capacity"
on public.permits
for insert
to authenticated
with check (exists (select 1 from public.residents where unit_id = permits.unit_id and user_id = auth.uid()) and revoked = false and valid_until >= current_date);

create policy "permits_update_plate_or_revoke"
on public.permits
for update
to authenticated
using (exists (select 1 from public.residents where unit_id = permits.unit_id and user_id = auth.uid()) or public.is_hoa_admin())
with check (exists (select 1 from public.residents where unit_id = permits.unit_id and user_id = auth.uid()) or public.is_hoa_admin());

revoke all on public.residents from anon, authenticated;
revoke all on public.hoa_admins from anon, authenticated;
revoke all on public.permits from anon, authenticated;

grant select on public.residents to authenticated;
grant select on public.hoa_admins to authenticated;
grant select, insert, update on public.permits to authenticated;

grant all on public.residents to service_role;
grant all on public.hoa_admins to service_role;
grant all on public.permits to service_role;

grant usage, select on all sequences in schema public to service_role;
```

